@Configuration
@EnableMethodSecurity
public class SecurityConfig {
    // Method security is now active
}

@Service
public class OrderService {

    @PreAuthorize("hasRole('ADMIN')")
    public void deleteAllOrders() {
        // Only ADMIN role can execute this
    }

    @PreAuthorize("#userId == authentication.principal.id")
    public Order getOrder(Long orderId, Long userId) {
        // User can only access their own orders
        return orderRepository.findById(orderId).orElseThrow();
    }

    @PreAuthorize("hasAuthority('ORDER_WRITE')")
    public Order createOrder(Order order) {
        return orderRepository.save(order);
    }
}

@Service
public class UserService {

    @PreAuthorize("hasRole('ADMIN')")
    public void deleteUser(Long userId) {
        userRepository.deleteById(userId);
    }

    @PreAuthorize("hasAuthority('USER_READ')")
    public User getUser(Long userId) {
        return userRepository.findById(userId).orElseThrow();
    }

    @PreAuthorize("#userId == authentication.principal.id")
    public void updateProfile(Long userId, ProfileDto profile) {
        // User can only update their own profile
        var user = userRepository.findById(userId).orElseThrow();
        user.setName(profile.name());
        userRepository.save(user);
    }

    @PreAuthorize("hasRole('ADMIN') or #userId == authentication.principal.id")
    public void changePassword(Long userId, String newPassword) {
        // Admin can change anyone's password, users can change their own
        var user = userRepository.findById(userId).orElseThrow();
        user.setPassword(passwordEncoder.encode(newPassword));
        userRepository.save(user);
    }
}

@Service
public class DocumentService {

    @PostAuthorize("returnObject.ownerId == authentication.principal.id")
    public Document getDocument(Long documentId) {
        // Method executes first, loads document
        return documentRepository.findById(documentId)
            .orElseThrow(() -> new DocumentNotFoundException(documentId));
    }

    @PostAuthorize("hasRole('ADMIN') or returnObject.isPublic == true")
    public Report getReport(Long reportId) {
        // Admins can see all reports, others only public ones
        return reportRepository.findById(reportId).orElseThrow();
    }

    // Better approach with @PreAuthorize when ownership is known
    @PreAuthorize("#ownerId == authentication.principal.id")
    public List<Document> getUserDocuments(Long ownerId) {
        // PreAuthorize prevents DB query for unauthorized users
        return documentRepository.findByOwnerId(ownerId);
    }
}

@SpringBootTest
@EnableMethodSecurity
class OrderServiceTest {

    @Autowired
    private OrderService orderService;

    @Test
    @WithMockUser(username = "user123", roles = "USER")
    void userCanAccessOwnOrder() {
        var order = orderService.getOrder(1L, 123L);
        assertNotNull(order);
    }

    @Test
    @WithMockUser(username = "user456", roles = "USER")
    void userCannotAccessOtherUsersOrder() {
        // UserId 123 is different from authenticated user 456
        assertThrows(AccessDeniedException.class, 
            () -> orderService.getOrder(1L, 123L));
    }

    @Test
    @WithMockUser(roles = "ADMIN")
    void adminCanDeleteAllOrders() {
        orderService.deleteAllOrders();
        // Success - no exception thrown
    }

    @Test
    @WithMockUser(roles = "USER")
    void regularUserCannotDeleteAllOrders() {
        assertThrows(AccessDeniedException.class, 
            () -> orderService.deleteAllOrders());
    }
}
